create table chdash_ui.wide_types(`id` UInt64, `created_on` Date, `long_identifier_for_visual_overflow_testing` String, `nullable_number` Nullable(Int64), `decimal_value` Decimal(18,6), `tuple_value` Tuple(code UInt16, name String), `nested_array` Array(Tuple(k String, v UInt64)), `tags` Map(String, String), `state` Enum8('new' = 1, 'processed' = 2, 'failed' = 3)) engine=MergeTree partition by toYYYYMM(created_on) order by (created_on, id) settings index_granularity=8192;
